// LA CONSOLA MANDA, Y SI NO CONTESTA NO SE BORRA NADA.
//
// Este flujo BORRA citas del calendario, asi que corre con la regla del flujo
// de recordatorios y no con la del conversacional: cuando no se sabe, no se
// hace nada. Diez minutos despues vuelve a intentar. Se sigue solo si el
// panel contesto 200 con el comercio activo Y la seña esta activa
// (`sena.activa`): sin seña no hay citas retenidas que vencer, y si un
// comercio la apago, lo que quedo pendiente lo resuelve una persona.
//
// Los minutos de retencion salen del panel (`sena.minutosRetencion`, 5..180),
// con el respaldo de `Config base` si viniera mal. Los calendarios a revisar
// son los mismos que mira el flujo de reservas: el del negocio y el de cada
// funcionario. Un calendario que no se mira es una cita retenida que nunca
// vence, y un horario perdido para siempre.
const base = $('Config base').first().json;
const respuesta = $input.first().json ?? {};
const codigo = Number(respuesta.statusCode);
const cuerpo = (respuesta.body ?? {});

const contesto = codigo === 200 && cuerpo && typeof cuerpo.tenantId === 'string';
const activo = contesto && String(cuerpo.estadoComercio || '') === 'activo';
const sena = (contesto && cuerpo.sena && typeof cuerpo.sena === 'object') ? cuerpo.sena : {};
if (!activo || sena.activa !== true) {
  // Ningun item = ninguna rama corre: ni consulta ni borrado.
  return [];
}

const minutosCrudo = sena.minutosRetencion;
const respaldo = Number(base.senaMinutosRetencion);
const minutosRetencion = (typeof minutosCrudo === 'number' && Number.isInteger(minutosCrudo)
  && minutosCrudo >= 5 && minutosCrudo <= 180) ? minutosCrudo
  : (Number.isInteger(respaldo) && respaldo >= 5 && respaldo <= 180 ? respaldo : 30);

const op = cuerpo.operacion ?? {};
const equipo = Array.isArray(cuerpo.funcionarios) ? cuerpo.funcionarios
  .map((f) => (f && (f.calendario || f.calendarioId)) || '').filter(Boolean) : [];
const calendarios = [...new Set([String(op.calendarioId || ''), ...equipo].filter(Boolean))];
if (!calendarios.length) return [];

return [{ json: {
  phoneNumberId: String(cuerpo.phoneNumberId || base.phoneNumberId || ''),
  minutosRetencion,
  calendarios,
  senaActiva: 'si',
  configDeLaConsola: true,
} }];

// Un item por cada calendario configurado: el nodo de Calendar corre una vez
// por item, asi se revisan TODAS las agendas (la del negocio y la de cada
// funcionario), igual que en «Calendarios a revisar» del flujo de reservas.
const cfg = $input.first().json;
const calendarios = Array.isArray(cfg.calendarios) ? cfg.calendarios : [];
return calendarios.map((calendarioARevisar) => ({ json: { ...cfg, calendarioARevisar } }));

// QUE CITAS RETENIDAS VENCIERON.
//
// Llegan los eventos de todos los calendarios (la consulta ya filtro por el
// texto «PENDIENTE DE SEÑA», pero Google busca en todo el evento, asi que se
// vuelve a mirar el TITULO: solo cuenta la cita cuyo titulo EMPIEZA con el
// prefijo que pone `agendar_cita`). Vence la que se creo hace mas de
// `minutosRetencion` minutos: `created` es la marca de Google, que no depende
// del reloj del flujo ni de lo que dijo el modelo.
//
// El telefono sale de la descripcion (`Telefono: 591…`, que escribe
// `agendar_cita`): sin el no se puede reportar al servidor, y entonces
// tampoco se borra: una cita con el prefijo y sin telefono no la creo este
// sistema, la mira una persona.
//
// SALE UN ITEM POR CITA VENCIDA, y el servidor decide (`senaVencida`): recien
// con su respuesta se borra. Nunca un mensaje al paciente: esto no escribe a
// WhatsApp, y no tiene con que hacerlo.
const cfg = $('Config de la seña').first().json;
const minutos = Number(cfg.minutosRetencion) || 30;
const ahora = Date.now();
const PREFIJO = /^PENDIENTE DE SEÑA · /;

const out = [];
for (const item of $input.all()) {
  const e = item.json;
  if (!e || !e.id || !PREFIJO.test(String(e.summary || ''))) continue;
  const creado = Date.parse(e.created || '');
  if (!Number.isFinite(creado) || (ahora - creado) < minutos * 60 * 1000) continue;
  const m = /Telefono:\s*\+?([0-9]{8,15})/i.exec(String(e.description || ''));
  if (!m) continue;
  out.push({ json: {
    eventoId: String(e.id),
    calendarioDelEvento: String((e.organizer && e.organizer.email) || ''),
    telefono: m[1],
    titulo: String(e.summary || ''),
    creadoEn: String(e.created || ''),
    minutosRetencion: minutos,
  } });
}
return out;
